(EXISTS(SELECT 1 FROM public.orders AS o, public.customer AS c, public.part AS p WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND p.p_partkey = lineitem.l_partkey AND lineitem.l_shipmode <> 'AIR' AND lineitem.l_discount <> lineitem.l_tax AND o.o_totalprice > 25000 AND o.o_totalprice <= 215000 AND NOT EXISTS(SELECT 1 FROM public.partsupp AS ps, public.supplier AS s WHERE ps.ps_partkey = p.p_partkey AND s.s_suppkey = ps.ps_suppkey AND lineitem.l_suppkey <> ps.ps_suppkey AND s.s_nationkey <= c.c_nationkey AND s.s_acctbal <= ps.ps_supplycost AND s.s_acctbal < c.c_acctbal AND EXISTS(SELECT 1 FROM public.nation AS n, public.region AS r WHERE n.n_nationkey = s.s_nationkey AND r.r_regionkey = n.n_regionkey AND r.r_name <> 'EUROPE')))) OR (EXISTS(SELECT 1 FROM public.orders AS o, public.customer AS c, public.part AS p WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND p.p_partkey = lineitem.l_partkey AND c.c_acctbal < lineitem.l_extendedprice AND EXISTS(SELECT 1 FROM "private_pg_followup_rls_view_20261101"."lineitem_inner" AS w WHERE w.l_partkey = lineitem.l_partkey AND w.l_suppkey <> lineitem.l_suppkey AND w.l_receiptdate < lineitem.l_receiptdate AND w.l_discount < lineitem.l_discount AND w.l_tax > lineitem.l_tax AND w.l_discount >= 0.01 AND w.l_discount <= 0.05) AND EXISTS(SELECT 1 FROM public.partsupp AS ps, public.supplier AS s WHERE ps.ps_partkey = p.p_partkey AND s.s_suppkey = ps.ps_suppkey AND lineitem.l_suppkey > ps.ps_suppkey AND s.s_nationkey <> c.c_nationkey AND s.s_acctbal >= ps.ps_supplycost)))